namespace{std::vector<int>phases,sounds,opened,closed;int resets,fades,launches;char committed[12];void Phase(void*,int p){phases.push_back(p);}void Cursor(void*,NameEntry*e,int d){e->cursor=(e->cursor+d+e->charset_len)%e->charset_len;}void Sound(void*,int x){sounds.push_back(x);}void Commit(void*,const char*n){std::strcpy(committed,n);}void Close(void*,int x){closed.push_back(x);}void Move(void*,ShotPracticeState*s,int d){s->selection=(s->selection+d+s->selection_count)%s->selection_count;}void Open(void*,int x){opened.push_back(x);}void Reset(void*){++resets;}void Fade(void*,float w,float h){assert(w==480&&h==384);++fades;}void Launch(void*,float x){assert(x==6);++launches;}}
