 ShotPracticeOps so={0,Phase,Move,Sound,Open,Close,Reset,Fade,Launch};ShotPracticeState s={0,1,0,0,0,{0},0};ShotPracticeEnv se={0,0,4,1,0,false,{true,false,true},0,0};ShotPracticeMenu_Update(&s,&se,&so);assert(s.selection_count==3&&s.selection==0&&s.unavailable_count==1&&s.unavailable[0]==1);s.phase=2;se.pressed=0x20;ShotPracticeMenu_Update(&s,&se,&so);assert(s.selection==1&&sounds.back()==12);se.pressed=0x1001;ShotPracticeMenu_Update(&s,&se,&so);assert(se.shot==1&&phases.back()==3);s.phase=3;s.phase_timer=10;se.pressed=0;ShotPracticeMenu_Update(&s,&se,&so);assert(fades==1&&sounds.back()==43);s.phase_timer=40;ShotPracticeMenu_Update(&s,&se,&so);assert(se.stage==7&&se.launch_state==7&&launches==1);
